import pytest

from app.errors import ValidationError
from app.features.discounts import apply_discount


def test_example_ten_percent():
    assert apply_discount("19.99", 10) == "$17.99"


def test_example_from_spec():
    assert apply_discount("20.00", 10) == "$18.00"


def test_zero_percent_is_unchanged():
    assert apply_discount("5.5", 0) == "$5.50"


def test_hundred_percent_is_free():
    assert apply_discount("12.34", 100) == "$0.00"


def test_discount_rounds_down_in_cents():
    # 1999 cents * 15 // 100 = 299 (discount); 1999 - 299 = 1700
    assert apply_discount("19.99", 15) == "$17.00"


def test_bare_integer_price():
    assert apply_discount("12", 50) == "$6.00"


@pytest.mark.parametrize("percent", [-1, 101, 1000])
def test_percent_out_of_range(percent):
    with pytest.raises(ValidationError):
        apply_discount("10.00", percent)


@pytest.mark.parametrize("percent", [10.0, "10", None, True])
def test_percent_not_int(percent):
    with pytest.raises(ValidationError):
        apply_discount("10.00", percent)


@pytest.mark.parametrize("price", ["abc", "", "1.234", "-5.00", "10.", "1,000"])
def test_invalid_price(price):
    with pytest.raises(ValidationError):
        apply_discount(price, 10)

